SELECT ?ts ?point ?class WHERE {
  ?zone a brick:Zone ; rdfs:label "Perimeter_bot_ZN_3" .
  ?point ref:isPointOf ?zone .
  ?point ?class .
  ?point ref:hasTimeseriesId ?ts .
}

SELECT ?ts ?point ?class WHERE {
  ?zone a brick:Zone ; rdfs:label "Perimeter_bot_ZN_3" .
  ?point brick:isPointOf ?zone ; ?class ?classval .
  ?point ref:hasTimeseriesId ?ts .
}

SELECT ?s ?p ?o WHERE {
  ?s ?p ?o .
  FILTER(str(?s) || str(?o) || str(?p) LIKE "%Perimeter_bot_ZN_3%")
} LIMIT 50

SELECT ?s ?p ?o WHERE {
  ?s a brick:Zone .
  FILTER(str(?s) LIKE "%Perimeter_bot_ZN_3%")
} LIMIT 50

SELECT ?point ?ts ?c WHERE {
  ?point brick:isPointOf <http://buildgraph.org/BG_large_office_2004_0000#Zone_F2_Z02> .
